d trend breakdown signal.\n    is_primary_downtrend = current_price < sma_50\n    is_momentum_confirming_down = macd_histogram < 0 and prev_macd_histogram >= 0\n    is_sentiment_permissive_for_sell = net_sentiment_score < 3.0\n    if is_primary_downtrend and is_momentum_confirming_down and is_sentiment_permissive_for_sell:\n        return "SELL"\n\n    # Priority 3: Profit-taking on extreme overbought conditions with FADING momentum.\n    is_momentum_fading = macd_hist_delta < 0\n    is_extremely_overbought = rsi > 82\n    if is_extremely_overbought and is_momentum_fading:\n        return "SELL"\n\n    # --- BUY LOGIC ---\n    is_primary_uptrend = current_price > sma_50\n    is_momentum_confirming_up = macd_histogram > 0 and prev_macd_histogram <= 0\n    is_not_overbought = rsi < 78\n    is_sentiment_permissive_for_buy = net_sentiment_score > -3.0 # Normal buy sentiment threshold\n    is_sufficient_volatility = short_atr > (long_atr * 0.6) # Avoids entering dead, sideways markets.\n\n    if is_primary_uptrend and is_momentum_confirming_up and is_not_overbought and is_sentiment_permissive_for_buy and is_sufficient_volatility:\n        return "BUY"\n\n    # Default action is to hold the current position.\n    return "HOLD"	1119ae4a93fe174f9576b0aafb5b9e69b9ff80f6730809c86d44194ba5b6030b	This self-improved strategy addresses stress regime vulnerabilities by refining the contrarian capitulation buy. It now requires stricter technical confirmation (RSI < 30, MACD momentum turning positive from negative territory) and explicit sentiment confirmation of extreme fear (`net_sentiment_score < -4.0`). The fixed 7% stop-loss is replaced with a dynamic ATR-based stop-loss, adapting to market volatility for better capital preservation. These changes aim to enhance resilience during crises and capture recovery opportunities, while maintaining robust performance in normal market conditions.	064e3f32-f3a1-4f05-a800-402eb82c3d03	2026-06-02 01:57:25.202557-04
2355aca6-fe9b-417f-a1e5-0add05723dec	46	evolution_gen_46	import numpy as np\nimport re\nimport math\n\n# --- Helper Functions for Technical Indicators ---\n\ndef calculate_ema_series(data, period):\n    """Calculates a full series of Exponential Moving Averages."""\n    if len(data) < period:\n        return np.array([])\n    data_arr = np.array(data, dtype=float)\n    try:\n        import pandas as pd\n        # Using pandas is preferred for accuracy and standard implementation\n        # .ewm(adjust=False) uses alpha = 2/(span+1) and initial value is the first data point.\n        # To align with typical EMA definition where the first EMA is SMA of first 'period' values,\n        # and subsequent EMAs use previous EMA, we need to adjust.\n        # A common approach for adjust=False is to use the first value as the initial EMA.\n        # For a series, pandas' ewm(adjust=False) starts calculating from the first value.\n        # If we want the first EMA to be the SMA of the first 'period' values, we need to seed it.\n        # The current implementation of pandas' ewm(span=period, adjust=False) effectively\n        # uses the first available data point as the initial EMA for the calculation.\n        # The slice [period-1:] ensures we get values after enough data points for the EMA to stabilize.\n        return pd.Series(data_arr).ewm(span=period, adjust=False).mean().to_numpy()[period-1:]\n    except ImportError:\n        # Fallback pure-python EMA calculation, using SMA for the first value\n        ema_values = np.zeros(len(data_arr) - period + 1, dtype=float)\n        ema_values[0] = np.mean(data_arr[:period])\n        multiplier = 2 / (period + 1)\n        for i in range(1, len(ema_values)):\n            ema_values[i] = (data_arr[i + period - 1] - ema_values[i-1]) * multiplier + ema_values[i-1]\n        return ema_values\n\ndef calculate_sma(prices, period):\n    """Calculates the Simple Moving Average (SMA) for the latest price."""\n    if len(prices) < period:\n        return None\n    return np.mean(prices[-period:])\n\ndef calculate_rsi(prices, period=14):\n    """Calculates the Relative Strength Index (RSI) using Wilder's smoothing method."""\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    deltas = np.diff(prices_arr)\n    \n    # Initial average gain/loss over the first 'period' deltas\n    seed_gains = deltas[:period][deltas[:period] >= 0].sum()\n    seed_losses = -deltas[:period][deltas[:period] < 0].sum()\n    \n    avg_gain = seed_gains / period\n    avg_loss = seed_losses / period\n    \n    # Wilder's smoothing for subsequent periods\n    for i in range(period, len(deltas)):\n        delta = deltas[i]\n        gain = delta if delta >= 0 else 0.0\n        loss = -delta if delta < 0 else 0.0\n        \n        avg_gain = (avg_gain * (period - 1) + gain) / period\n        avg_loss = (avg_loss * (period - 1) + loss) / period\n        \n    if avg_loss == 0:\n        return 100.0 # No losses, RSI is 100\n    \n    rs = avg_gain / avg_loss\n    return 100.0 - (100.0 / (1.0 + rs))\n\ndef calculate_macd_series(prices, short_period=12, long_period=26, signal_period=9):\n    """Calculates the MACD line, signal line, and histogram series."""\n    if len(prices) < long_period: # Need at least long_period for the first long EMA\n        return None, None, None\n    \n    short_ema_series = calculate_ema_series(prices, short_period)\n    long_ema_series = calculate_ema_series(prices, long_period)\n    \n    # MACD line is the difference between short and long EMA.\n    # Align the series lengths by taking the tail of the shorter EMA.\n    macd_line = short_ema_series[len(short_ema_series)-len(long_ema_series):] - long_ema_series\n    \n    if len(macd_line) < signal_period: # Need enough MACD line values for signal EMA\n        return macd_line, None, None\n        \n    signal_line = calculate_ema_series(macd_line, signal_period)\n    \n    # Histogram is MACD line minus signal line.\n    # Align the series lengths again.\n    histogram = macd_line[len(macd_line)-len(signal_line):] - signal_line\n    \n    return macd_line, signal_line, histogram\n\ndef calculate_atr(prices, period=14):\n    """Calculates Average True Range (ATR) using close-to-close volatility."""\n    # For simplicity and given only closing prices, ATR is approximated by\n    # the EMA of absolute daily price changes.\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    price_ranges = np.abs(np.diff(prices_arr)) # True Range approximation\n    \n    atr_series = calculate_ema_series(price_ranges, period)\n    return atr_series[-1] if len(atr_series) > 0 else None\n\ndef calculate_roc(prices, period=20):\n    """Calculates the Rate of Change (ROC) over a given period."""\n    if len(prices) < period + 1:\n        return None\n    # ROC = ((Current Price - Price N periods ago) / Price N periods ago) * 100\n    return ((prices[-1] - prices[-1 - period]) / prices[-1 - period]) * 100\n\ndef decide(current_price, price_history, news_context):\n    """\n    SELF-IMPROVED STRATEGY V3:\n    This version refines the strategy based on lessons from stress regimes:\n    1.  Capitulation Buy Enhancement: The contrarian "buy the dip" logic is now\n        independent of the general sentiment score. This allows it to trigger\n        during extreme market crashes (high ROC decline, low RSI, positive MACD\n        histogram delta) even when overall news sentiment is overwhelmingly negative,\n        addressing the issue of missed recovery entries during crises.\n    2.  Loosened Dynamic Stop-Loss: The percentage for the dynamic stop-loss is\n        adjusted from 7% to 8% (0.93 to 0.92). This provides slightly more room\n        for price fluctuations, aiming to reduce premature stop-outs during periods\n        of increased volatility, as observed in past stress regime performance.\n    3.  Maintains Robust Normal Regime Logic: The core trend-following and\n        momentum-based buy/sell signals, along with profit-taking in overbought\n        conditions, remain effective for stable market environments.\n    """\n    # --- 1. Sentiment Analysis ---\n    context_lower = news_context.lower()\n    sentiment_keywords = {\n        "fed pivot": 3.0, "rate cut": 2.5, "quantitative easing": 2.5, "soft landing": 2.5,\n        "cooling inflation": 2.5, "cpi miss": 2.5, "ai boom": 2.5, "stimulus": 2.0,\n        "dovish": 2.0, "record high": 2.0, "bullish": 2.0, "strong earnings": 2.0,\n        "beat estimates": 1.5, "recovery": 1.5, "upgrade": 1.5, "de-escalation": 2.0,\n        "short squeeze": 3.5, "capitulation": 3.0, "panic selling": 2.5, "extreme fear": 2.0,\n        "strong jobs report": 0.5, # Ambiguous: good for economy, bad for inflation/rates\n        "recession": -3.0, "crisis": -3.0, "stagflation": -3.0, "hot inflation": -3.0,\n        "war": -3.0, "yield curve inversion": -3.5, "quantitative tightening": -2.5,\n        "black swan": -4.0, "systemic risk": -4.0, "contagion": -3.5, "credit crunch": -3.5,\n        "rate hike": -2.5, "bankruptcy": -2.5, "hard landing": -2.5, "geopolitical risk": -2.5,\n        "cpi beat": -2.5, "vix spike": -2.5, "hawkish": -2.0, "bearish": -2.0,\n        "sell-off": -2.0, "weak earnings": -2.0, "market turmoil": -2.0, "bubble": -2.0,\n        "uncertainty": -1.5,\n        "euphoria": -2.5, "mania": -3.0, "irrational exuberance": -3.0, "extreme greed": -2.5,\n    }\n    negation_words = ["not", "no", "lack of", "fail to", "without", "struggle to", "avoids", "prevent"]\n    net_sentiment_score = 0.0\n    for keyword, weight in sentiment_keywords.items():\n        pattern = r'\\b' + re.escape(keyword) + r'\\b'\n        for match in re.finditer(pattern, context_lower):\n            pre_context = context_lower[max(0, match.start() - 30):match.start()]\n            is_negated = any(neg_word in pre_context for neg_word in negation_words)\n            net_sentiment_score += -weight if is_negated else weight\n\n    # --- 2. Technical Indicators & State Calculation ---\n    all_prices = price_history + [current_price]\n\n    # Indicator Periods\n    SMA_TREND_LONG = 100\n    SMA_TREND_MEDIUM = 50\n    RSI_PERIOD = 14\n    ATR_SHORT = 10\n    ATR_LONG = 50\n    ROC_CRASH_PERIOD = 20\n    STOP_LOSS_LOOKBACK = 20\n\n    # Ensure enough history for all indicators\n    required_history_length = max(SMA_TREND_LONG + 1, ATR_LONG + 1, ROC_CRASH_PERIOD + 1, RSI_PERIOD + 1, \n                                  26 + 9 + 1, STOP_LOSS_LOOKBACK + 1) # MACD requires long_period + signal_period for full series\n    if len(all_prices) < required_history_length:\n        return "HOLD"\n\n    # Calculate core indicators\n    sma_100 = calculate_sma(all_prices, SMA_TREND_LONG)\n    sma_50 = calculate_sma(all_prices, SMA_TREND_MEDIUM)\n    rsi = calculate_rsi(all_prices, RSI_PERIOD)\n    _, _, macd_hist_series = calculate_macd_series(all_prices)\n    short_atr = calculate_atr(all_prices, ATR_SHORT)\n    long_atr = calculate_atr(all_prices, ATR_LONG)\n    roc_20 = calculate_roc(all_prices, ROC_CRASH_PERIOD)\n    donchian_high_20 = np.max(all_prices[-STOP_LOSS_LOOKBACK:]) if len(all_prices) >= STOP_LOSS_LOOKBACK else None\n\n    # Null check for all indicators\n    if any(v is None for v in [sma_100, sma_50, rsi, short_atr, long_atr, roc_20, donchian_high_20]) or macd_hist_series is None or len(macd_hist_series) < 2:\n        return "HOLD"\n\n    macd_histogram = macd_hist_series[-1]\n    prev_macd_histogram = macd_hist_series[-2]\n    macd_hist_delta = macd_histogram - prev_macd_histogram\n\n    # --- 3. Regime Detection ---\n    # Crisis Regime: General high-risk environment\n    is_long_term_downtrend = current_price < sma_100\n    is_high_volatility = short_atr > (long_atr * 1.75)\n    is_crash_velocity = roc_20 < -15.0\n    is_crisis_regime = (is_long_term_downtrend and is_high_volatility) or is_crash_velocity\n\n    # Capitulation Regime: An extreme subset of crisis, signaling a potential bottom\n    is_deeply_oversold = rsi < 25\n    is_extreme_crash_velocity = roc_20 < -18.0\n    is_capitulation_candidate = is_extreme_crash_velocity and is_deeply_oversold\n\n    # --- 4. Decision Logic (Hierarchical) ---\n\n    # REGIME 1: CONTRARIAN CAPITULATION (HIGHEST PRIORITY)\n    # Buy when there is blood in the streets, but only if momentum shows signs of turning.\n    # Removed sentiment filter here to allow buys during extreme negative sentiment.\n    if is_capitulation_candidate and macd_hist_delta > 0:\n        return "BUY"\n\n    # REGIME 2: CRISIS AVERSION\n    # If in a general crisis (but not a specific capitulation buy signal), be defensive.\n    if is_crisis_regime:\n        # If momentum is negative or price is below medium-term trend, sell.\n        # Otherwise, hold current position (or cash if not in position).\n        if macd_histogram < 0 or current_price < sma_50:\n            return "SELL"\n        return "HOLD" # Hold cash and wait for the storm to pass, or hold existing position if conditions are not explicitly bearish.\n\n    # REGIME 3: NORMAL MARKET CONDITIONS\n\n    # --- SELL LOGIC (Risk Management First) ---\n    # Priority 1: Dynamic Stop-Loss. Loosened to 8% drop from 20-day high.\n    if current_price < (donchian_high_20 * 0.92): # Adjusted from 0.93 to 0.92\n        return "SELL"\n\n    # Priority 2: Standard trend breakdown signal.\n    is_primary_downtrend = current_price < sma_50\n    is_momentum_confirming_down = macd_histogram < 0 and prev_macd_histogram >= 0\n    is_sentiment_permissive_for_sell = net_sentiment_score < 3.0\n    if is_primary_downtrend and is_momentum_confirming_down and is_sentiment_permissive_for_sell:\n        return "SELL"\n\n    # Priority 3: Profit-taking on extreme overbought conditions with FADING momentum.\n    is_momentum_fading = macd_hist_delta < 0\n    is_extremely_overbought = rsi > 82\n    if is_extremely_overbought and is_momentum_fading:\n        return "SELL"\n\n    # --- BUY LOGIC ---\n    is_primary_uptrend = current_price > sma_50\n    is_momentum_confirming_up = macd_histogram > 0 and prev_macd_histogram <= 0\n    is_not_overbought = rsi < 78\n    is_sentiment_permissive_for_buy = net_sentiment_score > -3.0\n    is_sufficient_volatility = short_atr > (long_atr * 0.6) # Avoids entering dead, sideways markets.\n\n    if is_primary_uptrend and is_momentum_confirming_up and is_not_overbought and is_sentiment_permissive_for_buy and is_sufficient_volatility:\n        return "BUY"\n\n    # Default action is to hold the current position.\n    return "HOLD"	c6898e6c07b5069668aafcba33652f78cb72dc2e0b156d368a85ec30229b4884	This iteration enhances stress regime resilience by making the contrarian capitulation buy independent of general negative sentiment, allowing it to trigger during extreme fear. The dynamic stop-loss is slightly loosened from 7% to 8% to reduce premature exits in volatile markets, balancing capital preservation with allowing more room for price swings. Momentum velocity confirmation for sells and trend-following buys remain robust for normal conditions.	064e3f32-f3a1-4f05-a800-402eb82c3d03	2026-06-02 01:58:35.516425-04
be566482-336d-45ee-8087-80d181d0546c	47	evolution_gen_47	import numpy as np\nimport re\nimport math\n\n# --- Helper Functions for Technical Indicators ---\n\ndef calculate_ema_series(data, period):\n    """Calculates a full series of Exponential Moving Averages."""\n    if len(data) < period:\n        return np.array([])\n    data_arr = np.array(data, dtype=float)\n    try:\n        import pandas as pd\n        # Using pandas is preferred for accuracy and standard implementation\n        # .ewm(adjust=False) uses alpha = 2/(span+1) and initial value is the first data point.\n        # The slice [period-1:] ensures we get values after enough data points for the EMA to stabilize.\n        return pd.Series(data_arr).ewm(span=period, adjust=False).mean().to_numpy()[period-1:]\n    except ImportError:\n        # Fallback pure-python EMA calculation, using SMA for the first value\n        ema_values = np.zeros(len(data_arr) - period + 1, dtype=float)\n        ema_values[0] = np.mean(data_arr[:period])\n        multiplier = 2 / (period + 1)\n        for i in range(1, len(ema_values)):\n            ema_values[i] = (data_arr[i + period - 1] - ema_values[i-1]) * multiplier + ema_values[i-1]\n        return ema_values\n\ndef calculate_sma(prices, period):\n    """Calculates the Simple Moving Average (SMA) for the latest price."""\n    if len(prices) < period:\n        return None\n    return np.mean(prices[-period:])\n\ndef calculate_rsi(prices, period=14):\n    """Calculates the Relative Strength Index (RSI) using Wilder's smoothing method."""\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    deltas = np.diff(prices_arr)\n    \n    # Initial average gain/loss over the first 'period' deltas\n    seed_gains = deltas[:period][deltas[:period] >= 0].sum()\n    seed_losses = -deltas[:period][deltas[:period] < 0].sum()\n    \n    avg_gain = seed_gains / period\n    avg_loss = seed_losses / period\n    \n    # Wilder's smoothing for subsequent periods\n    for i in range(period, len(deltas)):\n        delta = deltas[i]\n        gain = delta if delta >= 0 else 0.0\n        loss = -delta if delta < 0 else 0.0\n        \n        avg_gain = (avg_gain * (period - 1) + gain) / period\n        avg_loss = (avg_loss * (period - 1) + loss) / period\n        \n    if avg_loss == 0:\n        return 100.0 # No losses, RSI is 100\n    \n    rs = avg_gain / avg_loss\n    return 100.0 - (100.0 / (1.0 + rs))\n\ndef calculate_macd_series(prices, short_period=12, long_period=26, signal_period=9):\n    """Calculates the MACD line, signal line, and histogram series."""\n    if len(prices) < long_period: # Need at least long_period for the first long EMA\n        return None, None, None\n    \n    short_ema_series = calculate_ema_series(prices, short_period)\n    long_ema_series = calculate_ema_series(prices, long_period)\n    \n    # MACD line is the difference between short and long EMA.\n    # Align the series lengths by taking the tail of the shorter EMA.\n    macd_line = short_ema_series[len(short_ema_series)-len(long_ema_series):] - long_ema_series\n    \n    if len(macd_line) < signal_period: # Need enough MACD line values for signal EMA\n        return macd_line, None, None\n        \n    signal_line = calculate_ema_series(macd_line, signal_period)\n    \n    # Histogram is MACD line minus signal line.\n    # Align the series lengths again.\n    histogram = macd_line[len(macd_line)-len(signal_line):] - signal_line\n    \n    return macd_line, signal_line, histogram\n\ndef calculate_atr(prices, period=14):\n    """Calculates Average True Range (ATR) using close-to-close volatility."""\n    # For simplicity and given only closing prices, ATR is approximated by\n    # the EMA of absolute daily price changes.\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    price_ranges = np.abs(np.diff(prices_arr)) # True Range approximation\n    \n    atr_series = calculate_ema_series(price_ranges, period)\n    return atr_series[-1] if len(atr_series) > 0 else None\n\ndef calculate_roc(prices, period=20):\n    """Calculates the Rate of Change (ROC) over a given period."""\n    if len(prices) < period + 1:\n        return None\n    # ROC = ((Current Price - Price N periods ago) / Price N periods ago) * 100\n    return ((prices[-1] - prices[-1 - period]) / prices[-1 - period]) * 100\n\ndef decide(current_price, price_history, news_context):\n    """\n    SELF-IMPROVED STRATEGY V4:\n    This version refines the strategy based on lessons from stress regimes,\n    aiming to improve recovery capture and adaptive risk management:\n    1.  Enhanced Capitulation Buy: The contrarian "buy the dip" logic now\n        requires an immediate short-term bounce confirmation (today's price\n        higher than yesterday's close) in addition to extreme technicals\n        (ROC decline, low RSI, positive MACD histogram delta). This aims to\n        reduce false early entries during capitulation.\n    2.  Crisis Recovery Buy: Introduced a new buy signal specifically for\n        the recovery phase of a crisis. This allows re-entry when the market\n        starts to stabilize and show signs of a V-shaped recovery (price above\n        medium-term SMA, RSI bouncing from oversold, positive MACD histogram).\n    3.  Adaptive Stop-Loss: Replaced the fixed percentage dynamic stop-loss\n        with an ATR-based trailing stop, calculated from the 20-day high.\n        This stop-loss is more adaptive to market volatility, providing more\n        room during high volatility and tightening during low volatility,\n        reducing premature stop-outs.\n    4.  Maintains Robust Normal Regime Logic: The core trend-following and\n        momentum-based buy/sell signals, along with profit-taking in overbought\n        conditions, remain effective for stable market environments.\n    """\n    # --- 1. Sentiment Analysis ---\n    context_lower = news_context.lower()\n    sentiment_keywords = {\n        "fed pivot": 3.0, "rate cut": 2.5, "quantitative easing": 2.5, "soft landing": 2.5,\n        "cooling inflation": 2.5, "cpi miss": 2.5, "ai boom": 2.5, "stimulus": 2.0,\n        "dovish": 2.0, "record high": 2.0, "bullish": 2.0, "strong earnings": 2.0,\n        "beat estimates": 1.5, "recovery": 1.5, "upgrade": 1.5, "de-escalation": 2.0,\n        "short squeeze": 3.5, "capitulation": 3.0, "panic selling": 2.5, "extreme fear": 2.0,\n        "strong jobs report": 0.5, # Ambiguous: good for economy, bad for inflation/rates\n        "recession": -3.0, "crisis": -3.0, "stagflation": -3.0, "hot inflation": -3.0,\n        "war": -3.0, "yield curve inversion": -3.5, "quantitative tightening": -2.5,\n        "black swan": -4.0, "systemic risk": -4.0, "contagion": -3.5, "credit crunch": -3.5,\n        "rate hike": -2.5, "bankruptcy": -2.5, "hard landing": -2.5, "geopolitical risk": -2.5,\n        "cpi beat": -2.5, "vix spike": -2.5, "hawkish": -2.0, "bearish": -2.0,\n        "sell-off": -2.0, "weak earnings": -2.0, "market turmoil": -2.0, "bubble": -2.0,\n        "uncertainty": -1.5,\n        "euphoria": -2.5, "mania": -3.0, "irrational exuberance": -3.0, "extreme greed": -2.5,\n    }\n    negation_words = ["not", "no", "lack of", "fail to", "without", "struggle to", "avoids", "prevent"]\n    net_sentiment_score = 0.0\n    for keyword, weight in sentiment_keywords.items():\n        pattern = r'\\b' + re.escape(keyword) + r'\\b'\n        for match in re.finditer(pattern, context_lower):\n            pre_context = context_lower[max(0, match.start() - 30):match.start()]\n            is_negated = any(neg_word in pre_context for neg_word in negation_words)\n            net_sentiment_score += -weight if is_negated else weight\n\n    # --- 2. Technical Indicators & State Calculation ---\n    all_prices = price_history + [current_price]\n\n    # Indicator Periods\n    SMA_TREND_LONG = 100\n    SMA_TREND_MEDIUM = 50\n    RSI_PERIOD = 14\n   