ca7cc682-9ddd-4458-a47e-f8d5e79df903	97	evolution_gen_97	import numpy as np\nimport re\nimport math\n\n# --- Helper Functions for Technical Indicators ---\n\ndef calculate_ema_series(data, period):\n    """Calculates a full series of Exponential Moving Averages."""\n    if len(data) < period:\n        return np.array([])\n    data_arr = np.array(data, dtype=float)\n    try:\n        import pandas as pd\n        # Using pandas is preferred for accuracy and standard implementation\n        # .ewm(adjust=False) uses alpha = 2/(span+1) and initial value is the first data point.\n        # The slice [period-1:] ensures we get values after enough data points for the EMA to stabilize.\n        return pd.Series(data_arr).ewm(span=period, adjust=False).mean().to_numpy()[period-1:]\n    except ImportError:\n        # Fallback pure-python EMA calculation, using SMA for the first value\n        ema_values = np.zeros(len(data_arr) - period + 1, dtype=float)\n        if len(data_arr) >= period:\n            ema_values[0] = np.mean(data_arr[:period])\n            multiplier = 2 / (period + 1)\n            for i in range(1, len(ema_values)):\n                ema_values[i] = (data_arr[i + period - 1] - ema_values[i-1]) * multiplier + ema_values[i-1]\n        return ema_values\n\ndef calculate_sma(prices, period):\n    """Calculates the Simple Moving Average (SMA) for the latest price."""\n    if len(prices) < period:\n        return None\n    return np.mean(prices[-period:])\n\ndef calculate_rsi(prices, period=14):\n    """Calculates the Relative Strength Index (RSI) using Wilder's smoothing method."""\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    deltas = np.diff(prices_arr)\n    \n    # Initial average gain/loss over the first 'period' deltas\n    seed_gains = deltas[:period][deltas[:period] >= 0].sum()\n    seed_losses = -deltas[:period][deltas[:period] < 0].sum()\n    \n    avg_gain = seed_gains / period\n    avg_loss = seed_losses / period\n    \n    # Wilder's smoothing for subsequent periods\n    for i in range(period, len(deltas)):\n        delta = deltas[i]\n        gain = delta if delta >= 0 else 0.0\n        loss = -delta if delta < 0 else 0.0\n        \n        avg_gain = (avg_gain * (period - 1) + gain) / period\n        avg_loss = (avg_loss * (period - 1) + loss) / period\n        \n    if avg_loss == 0:\n        return 100.0 # No losses, RSI is 100\n    \n    rs = avg_gain / avg_loss\n    return 100.0 - (100.0 / (1.0 + rs))\n\ndef calculate_macd_series(prices, short_period=12, long_period=26, signal_period=9):\n    """Calculates the MACD line, signal line, and histogram series."""\n    if len(prices) < long_period: # Need at least long_period for the first long EMA\n        return None, None, None\n    \n    short_ema_series = calculate_ema_series(prices, short_period)\n    long_ema_series = calculate_ema_series(prices, long_period)\n    \n    if len(short_ema_series) == 0 or len(long_ema_series) == 0:\n        return None, None, None\n\n    # MACD line is the difference between short and long EMA.\n    # Align the series lengths by taking the tail of the shorter EMA.\n    macd_line = short_ema_series[len(short_ema_series)-len(long_ema_series):] - long_ema_series\n    \n    if len(macd_line) < signal_period: # Need enough MACD line values for signal EMA\n        return macd_line, None, None\n        \n    signal_line = calculate_ema_series(macd_line, signal_period)\n    \n    if len(signal_line) == 0:\n        return macd_line, None, None\n\n    # Histogram is MACD line minus signal line.\n    # Align the series lengths again.\n    histogram = macd_line[len(macd_line)-len(signal_line):] - signal_line\n    \n    return macd_line, signal_line, histogram\n\ndef calculate_atr(prices, period=14):\n    """Calculates Average True Range (ATR) using close-to-close volatility."""\n    # For simplicity and given only closing prices, ATR is approximated by\n    # the EMA of absolute daily price changes.\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    price_ranges = np.abs(np.diff(prices_arr)) # True Range approximation\n    \n    atr_series = calculate_ema_series(price_ranges, period)\n    return atr_series[-1] if len(atr_series) > 0 else None\n\ndef calculate_roc(prices, period=20):\n    """Calculates the Rate of Change (ROC) over a given period."""\n    if len(prices) < period + 1:\n        return None\n    # ROC = ((Current Price - Price N periods ago) / Price N periods ago) * 100\n    if prices[-1 - period] == 0: # Avoid division by zero\n        return 0.0\n    return ((prices[-1] - prices[-1 - period]) / prices[-1 - period]) * 100\n\ndef decide(current_price, price_history, news_context):\n    """\n    SELF-IMPROVED STRATEGY V8:\n    This version refines the strategy based on lessons from stress regimes, particularly\n    aiming to improve participation in V-shaped recoveries during crises while mitigating\n    premature entries and stop-outs.\n\n    Key Improvements:\n    1.  More Permissive Crisis Recovery/Capitulation Buys:\n        -   Capitulation Buy now triggers on `macd_hist_delta > 0` (improving momentum) and `rsi < 30` (deeply oversold but slightly less extreme), allowing earlier entry into potential bottoms.\n        -   Post-Crisis Recovery Buy now triggers on `macd_hist_delta > 0` and `rsi > 35` (recovering from oversold), aiming to capture earlier bounces.\n    2.  Wider Dynamic Stop-Loss for Extreme Volatility: The stop-loss is now even wider (20%) during periods of extreme volatility, providing more room for price swings and reducing premature stop-outs in highly turbulent markets.\n    3.  Sentiment Refinement: Neutralized "strong jobs report" sentiment to avoid ambiguity in varying macro environments.\n    4.  Maintains Robust Normal Regime Logic: The core trend-following and momentum-based buy/sell signals, along with profit-taking in overbought conditions,