rice_history + [current_price]\n\n    # Indicator Periods\n    SMA_TREND_LONG = 100\n    SMA_TREND_MEDIUM = 50\n    RSI_PERIOD = 14\n    ATR_SHORT = 10\n    ATR_LONG = 50\n    ROC_CRASH_PERIOD = 20\n    STOP_LOSS_LOOKBACK = 30 # Increased lookback for stop-loss\n\n    # Ensure enough history for all indicators\n    required_history_length = max(SMA_TREND_LONG + 1, ATR_LONG + 1, ROC_CRASH_PERIOD + 1, RSI_PERIOD + 1, \n                                  26 + 9 + 1, STOP_LOSS_LOOKBACK + 1) # MACD requires long_period + signal_period for full series\n    if len(all_prices) < required_history_length:\n        return "HOLD"\n\n    # Calculate core indicators\n    sma_100 = calculate_sma(all_prices, SMA_TREND_LONG)\n    sma_50 = calculate_sma(all_prices, SMA_TREND_MEDIUM)\n    rsi = calculate_rsi(all_prices, RSI_PERIOD)\n    macd_line, signal_line, macd_hist_series = calculate_macd_series(all_prices)\n    short_atr = calculate_atr(all_prices, ATR_SHORT)\n    long_atr = calculate_atr(all_prices, ATR_LONG)\n    roc_20 = calculate_roc(all_prices, ROC_CRASH_PERIOD)\n    donchian_high_30 = np.max(all_prices[-STOP_LOSS_LOOKBACK:]) if len(all_prices) >= STOP_LOSS_LOOKBACK else None\n\n    # Null check for all indicators\n    if any(v is None for v in [sma_100, sma_50, rsi, short_atr, long_atr, roc_20, donchian_high_30]) or \\\n       macd_hist_series is None or len(macd_hist_series) < 2:\n        return "HOLD"\n\n    macd_histogram = macd_hist_series[-1]\n    prev_macd_histogram = macd_hist_series[-2]\n    macd_hist_delta = macd_histogram - prev_macd_histogram\n\n    # --- 3. Regime Detection ---\n    # Volatility thresholds for adaptive stop-loss\n    is_high_volatility = short_atr > (long_atr * 1.75)\n    is_extreme_volatility = short_atr > (long_atr * 2.0) # New, higher threshold for extreme conditions\n\n    # Crisis Regime: General high-risk environment\n    is_long_term_downtrend = current_price < sma_100\n    is_crash_velocity = roc_20 < -15.0\n    is_crisis_regime = (is_lo